ValidationRule.errorConditionFormula:
AND(
    NOT(ISNEW()),
    ISCHANGED(Estado__c),
    NOT(
        OR(
            AND(
                ISPICKVAL(PRIORVALUE(Estado__c), "Pendiente"),
                OR(ISPICKVAL(Estado__c, "En curso"), ISPICKVAL(Estado__c, "Cerrado"), ISPICKVAL(Estado__c, "Descartado"))
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Estado__c), "En curso"),
                OR(ISPICKVAL(Estado__c, "Cerrado"), ISPICKVAL(Estado__c, "Descartado"))
            )
        )
    )
)
